// hcpu_dashboard.v — the painter, and it only paints what is true.
//
// The static layout lives in the text RAM's initial contents, generated by
// rtl/scripts/gen_dashboard.py. This module writes the handful of cells that
// carry live values, once per frame, during blanking.
//
// ── eight slots of sixteen cells, and nothing else moves ────────
// A field walker rather than a string engine: `idx` counts 0..127, its top
// three bits pick the field and its low four pick the position inside it.
// Every write is one cell, and the whole pass is 128 writes against a frame
// of 1,237,500 pixel clocks. There is no arbitration with the renderer
// because the text RAM has a write port and a read port.
//
// ── which fields are real, and it is a short list ───────────────
// Six, and every one of them comes from a signal that already existed at the
// wrapper boundary before M5 touched anything:
//
//   STATE        hcpu_top's `halted` output
//   PC           imem_addr, the fetch address
//   INSTRUCTION  imem_data, the word at that address
//   CYCLE        the wrapper's own cycle counter
//   FLAGS        hcpu_top's dbg_flags, which was tied off until now
//   GUARD        hcpu_top's `guard_led`
//
// PID, PROCESS, TRAP, PIPELINE, and every module in the stack and device
// panels have NO WIRE. They are spelled NOT INSTRUMENTED in the static image
// and this module never writes over them. That is not a placeholder to be
// filled in later by guessing -- it is the honest state of a machine whose
// telemetry is one snapshot deep.
//
// ── the page button changes one digit and one line, for now ─────
// Pages 1..8 have no content because their content is the telemetry that
// does not exist. Painting eight elaborate empty panels would be the
// decorative dashboard this project was told not to build, so the page
// number moves and a single line says what is behind it.

`default_nettype none

`include "hcpu_dashboard_pos.vh"

module hcpu_dashboard #(
    parameter PCW = 12
) (
    input  wire        clk,            // pixel_clk
    input  wire        rst_n,

    input  wire        frame_tick,     // start of frame: repaint
    input  wire [3:0]  page,

    input  wire [PCW-1:0] snap_pc,
    input  wire [31:0]    snap_instr,
    input  wire           snap_halted,
    input  wire           snap_guard,
    input  wire [31:0]    snap_cycles,
    input  wire [7:0]     snap_flags,
    input  wire           snap_valid,

    output reg         we,
    output reg  [13:0] waddr,
    output reg  [15:0] wdata,
    output wire        sample          // ask telemetry for a fresh set
);

    localparam [3:0] C_DIM   = 4'd0, C_WHITE = 4'd1, C_CYAN  = 4'd2,
                     C_GREEN = 4'd3, C_YELLOW= 4'd4, C_RED   = 4'd5,
                     C_BLUE  = 4'd6, C_GOLD  = 4'd7;

    // One snapshot per frame, taken at the top of the frame so every field on
    // the screen belongs to the same instant.
    assign sample = frame_tick;

    reg [7:0] idx;
    reg       running;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            idx     <= 8'd0;
            running <= 1'b0;
        end else if (frame_tick) begin
            idx     <= 8'd0;
            running <= 1'b1;
        end else if (running) begin
            if (idx == 8'd127) running <= 1'b0;
            idx <= idx + 8'd1;
        end
    end

    wire [2:0] field = idx[6:4];
    wire [3:0] pos   = idx[3:0];

    function [7:0] hexd;
        input [3:0] n;
        hexd = (n < 4'd10) ? (8'h30 + {4'd0, n}) : (8'h41 + {4'd0, n} - 8'd10);
    endfunction

    // A nibble picked out of a 32-bit word by position: pos 2 is the top
    // nibble, pos 9 the bottom, because the two cells before it are "0X".
    function [7:0] hex32;
        input [31:0] v;
        input [3:0]  p;
        case (p)
            4'd2: hex32 = hexd(v[31:28]);
            4'd3: hex32 = hexd(v[27:24]);
            4'd4: hex32 = hexd(v[23:20]);
            4'd5: hex32 = hexd(v[19:16]);
            4'd6: hex32 = hexd(v[15:12]);
            4'd7: hex32 = hexd(v[11:8]);
            4'd8: hex32 = hexd(v[7:4]);
            4'd9: hex32 = hexd(v[3:0]);
            default: hex32 = 8'h20;
        endcase
    endfunction

    // "NOT INSTRUMENTED", sixteen cells, indexed rather than stored.
    function [7:0] ni_char;
        input [3:0] p;
        case (p)
            4'd0: ni_char = "N"; 4'd1: ni_char = "O"; 4'd2: ni_char = "T";
            4'd3: ni_char = " "; 4'd4: ni_char = "I"; 4'd5: ni_char = "N";
            4'd6: ni_char = "S"; 4'd7: ni_char = "T"; 4'd8: ni_char = "R";
            4'd9: ni_char = "U"; 4'd10: ni_char = "M"; 4'd11: ni_char = "E";
            4'd12: ni_char = "N"; 4'd13: ni_char = "T"; 4'd14: ni_char = "E";
            default: ni_char = "D";
        endcase
    endfunction

    reg [7:0]  ch;
    reg [3:0]  at;
    reg [13:0] base;

    always @* begin
        ch   = 8'h20;
        at   = C_DIM;
        base = `DASH_STATE_ADDR;

        case (field)
        // ── STATE ───────────────────────────────────────────────
        3'd0: begin
            base = `DASH_STATE_ADDR;
            at   = snap_halted ? C_RED : C_GREEN;
            if (!snap_valid) begin
                at = C_DIM;
                ch = ni_char(pos);
            end else case (pos)
                4'd0: ch = snap_halted ? "H" : "R";
                4'd1: ch = snap_halted ? "A" : "U";
                4'd2: ch = snap_halted ? "L" : "N";
                4'd3: ch = snap_halted ? "T" : "N";
                4'd4: ch = snap_halted ? "E" : "I";
                4'd5: ch = snap_halted ? "D" : "N";
                4'd6: ch = snap_halted ? " " : "G";
                default: ch = " ";
            endcase
        end
        // ── PC ──────────────────────────────────────────────────
        3'd1: begin
            base = `DASH_PC_ADDR;
            at   = C_WHITE;
            case (pos)
                4'd0: ch = "0";
                4'd1: ch = "X";
                4'd2: ch = hexd(snap_pc[11:8]);
                4'd3: ch = hexd(snap_pc[7:4]);
                4'd4: ch = hexd(snap_pc[3:0]);
                default: ch = " ";
            endcase
        end
        // ── INSTRUCTION ─────────────────────────────────────────
        3'd2: begin
            base = `DASH_INSTR_ADDR;
            at   = C_WHITE;
            case (pos)
                4'd0: ch = "0";
                4'd1: ch = "X";
                default: ch = hex32(snap_instr, pos);
            endcase
        end
        // ── CYCLE ───────────────────────────────────────────────
        3'd3: begin
            base = `DASH_CYCLE_ADDR;
            at   = C_WHITE;
            case (pos)
                4'd0: ch = "0";
                4'd1: ch = "X";
                default: ch = hex32(snap_cycles, pos);
            endcase
        end
        // ── FLAGS ───────────────────────────────────────────────
        3'd4: begin
            base = `DASH_FLAGS_ADDR;
            at   = C_WHITE;
            case (pos)
                4'd0: ch = "0";
                4'd1: ch = "X";
                4'd2: ch = hexd(snap_flags[7:4]);
                4'd3: ch = hexd(snap_flags[3:0]);
                default: ch = " ";
            endcase
        end
        // ── GUARD ───────────────────────────────────────────────
        // guard_led is the live GUARD flag. High means a guard has caught
        // something, so the green case is the one where it is low.
        3'd5: begin
            base = `DASH_GUARD_ADDR;
            at   = snap_guard ? C_RED : C_GREEN;
            case (pos)
                4'd0: ch = snap_guard ? "F" : "O";
                4'd1: ch = snap_guard ? "A" : "K";
                4'd2: ch = snap_guard ? "U" : " ";
                4'd3: ch = snap_guard ? "L" : " ";
                4'd4: ch = snap_guard ? "T" : " ";
                default: ch = " ";
            endcase
        end
        // ── the page digit ──────────────────────────────────────
        3'd6: begin
            base = `DASH_PAGE_ADDR;
            at   = C_WHITE;
            ch   = (pos == 4'd0) ? hexd(page) : 8'h20;
        end
        // ── the banner pages 1..8 carry ─────────────────────────
        default: begin
            base = `DASH_BANNER_ADDR;
            at   = C_YELLOW;
            ch   = (page == 4'd0) ? 8'h20 : ni_char(pos);
        end
        endcase
    end

    // The page digit is one cell wide; writing sixteen would run over the
    // label beside it. Every other field owns its whole slot.
    wire in_range = (field == 3'd6) ? (pos == 4'd0) : 1'b1;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            we    <= 1'b0;
            waddr <= 14'd0;
            wdata <= 16'd0;
        end else begin
            we    <= running & in_range;
            waddr <= base + {10'd0, pos};
            wdata <= {4'd0, at, ch};
        end
    end

endmodule

`default_nettype wire
